package ical

import (
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"testing"
	"time"

	goical "github.com/emersion/go-ical"
)

// TestExpandDSTOverrideMatchesSabre pins recurrence expansion across a DST
// transition — including an overridden instance whose RECURRENCE-ID sits
// after the spring-forward — against sabre/vobject's expand() output
// (testdata/dst-override-expanded.ics, regenerated by
// scripts/expand-golden.php). This settles the occStart.Unix() override
// matching and wall-clock-preservation questions from review.
func TestExpandDSTOverrideMatchesSabre(t *testing.T) {
	src, err := os.ReadFile(filepath.Join("testdata", "dst-override.ics"))
	if err != nil {
		t.Fatal(err)
	}
	cal, err := Decode(src)
	if err != nil {
		t.Fatal(err)
	}
	expanded, err := Expand(cal,
		time.Date(2026, 3, 23, 0, 0, 0, 0, time.UTC),
		time.Date(2026, 4, 5, 0, 0, 0, 0, time.UTC),
		time.UTC)
	if err != nil {
		t.Fatalf("Expand: %v", err)
	}

	goldenRaw, err := os.ReadFile(filepath.Join("testdata", "dst-override-expanded.ics"))
	if err != nil {
		t.Fatal(err)
	}
	golden, err := Decode(goldenRaw)
	if err != nil {
		t.Fatal(err)
	}

	got, want := instanceKeys(expanded), instanceKeys(golden)
	if strings.Join(got, "\n") != strings.Join(want, "\n") {
		t.Errorf("expanded instances differ from sabre:\n--- ours ---\n%s\n--- sabre ---\n%s",
			strings.Join(got, "\n"), strings.Join(want, "\n"))
	}
}

// instanceKeys summarizes each VEVENT as its identifying fields, sorted.
func instanceKeys(cal *goical.Calendar) []string {
	var out []string
	for _, comp := range cal.Children {
		if comp.Name != goical.CompEvent {
			continue
		}
		get := func(name string) string {
			if p := comp.Props.Get(name); p != nil {
				return p.Value
			}
			return ""
		}
		out = append(out, fmt.Sprintf("start=%s end=%s rid=%s summary=%q",
			get("DTSTART"), get("DTEND"), get("RECURRENCE-ID"), get("SUMMARY")))
	}
	sort.Strings(out)
	return out
}
